# Line-by-Line Comments for `pickKeys`

```typescript
// A generic utility that creates a new object containing only the specified keys
// from the source object. T is the source object's type, and K is constrained to
// the keys of T (defaulting to all keys of T if not specified). The return type
// Pick<T, K> reflects that only the requested keys will be present.
export const pickKeys = <T, K extends keyof T = keyof T>(obj: T, ...keys: K[]): Pick<T, K> => {

  // Reduce the list of requested keys into a new accumulator object, starting
  // from an empty object typed as Pick<T, K>. For each key, we conditionally
  // copy the value from `obj` into the result.
  return keys.reduce((acc, key) => {

    // Guard: only copy the key if it actually exists on `obj` (using our
    // `hasKey` type-guard helper). This handles cases where a key might be
    // `undefined`/missing at runtime despite passing the TS type check,
    // and it also narrows `key` for the following assignment.
    if (hasKey(obj, key)) {

      // Assign the value from the source object to the same key on the
      // accumulator. TypeScript accepts this because `hasKey` narrowed the
      // key to a guaranteed-present key of T, and `acc` is typed as Pick<T, K>.
      acc[key] = obj[key];
    }

    // Return the accumulator so the next iteration can add to it.
    return acc;

  // Provide the empty object as the initial accumulator value, cast to the
  // target Pick<T, K> type so the reduce callback's accumulated type is correct.
  }, {} as Pick<T, K>);
};
```

